// Get HubSpot posts from HTTP Request node
const hubspotItems = $('HTTP Request').all();

// Get existing HubSpot IDs from Fibery (HTTP Request2)
const fiberyResult = $('HTTP Request2').first().json;
const existingPosts = {};

// Build a map of HubSpot ID → Fibery ID
if (fiberyResult?.result) {
  for (const entity of fiberyResult.result) {
    const hubspotId = entity['Marketing Operations/HubSpot ID'];
    const fiberyId = entity['fibery/id'];
    if (hubspotId && fiberyId) {
      existingPosts[String(hubspotId)] = fiberyId;
    }
  }
}

const statusMap = {
  'WAITING': '3538c7b0-f785-11f0-8fd1-d5837c28f286',
  'SUCCESS': '458301d1-f785-11f0-8fd1-d5837c28f286',
  'CANCELED': '56a1f110-f785-11f0-8fd1-d5837c28f286'
};

// Build ALL commands in one array
const allCommands = [];

for (const item of hubspotItems) {
  const post = item.json;

  // Get broadcastId and convert to string
  const broadcastId = String(post.broadcastGuid);

  // Get title from content.title
  const title = post.content?.title || 'Untitled Post';

  // Get body for Success metrics
  const body = post.content?.body || post.messageText || '';

  // Convert triggerAt timestamp to date (YYYY-MM-DD)
  const triggerAt = post.triggerAt;
  const pubDate = triggerAt ? new Date(triggerAt).toISOString().split('T')[0] : null;

  // Build HubSpot URL with broadcastGuid
  const hubspotUrl = `https://app.hubspot.com/social/5369249/manage/published?broadcast=${broadcastId}`;

  // Get media URL from extraData.files
  const mediaUrl = post.extraData?.files?.[0]?.url || null;

  // Get media type from extraData.files
  const mediaType = post.extraData?.files?.[0]?.mediaType || null;

  // Get status ID
  const hubspotStatus = post.status || 'WAITING';
  const fiberyStatusId = statusMap[hubspotStatus] || statusMap['WAITING'];

  // Get channel from channelKey
  const channelKey = post.channelKey || '';
  const channel = channelKey.includes('LinkedIn') ? 'LinkedIn' : 
                  channelKey.includes('Facebook') ? 'Facebook' :
                  channelKey.includes('Twitter') ? 'Twitter' : 'Other';

  // Combine channel + body for Success metrics
  const successMetrics = channel + ": " + body;

  // Check if post already exists
  if (existingPosts[broadcastId]) {
    // UPDATE existing post
    allCommands.push({
      "command": "fibery.entity/update",
      "args": {
        "type": "Marketing Operations/All Marketing Projects",
        "entity": {
          "fibery/id": existingPosts[broadcastId],
          "Marketing Operations/name": title,
          "Marketing Operations/Due Date": pubDate,
          "Marketing Operations/Status": {
            "fibery/id": fiberyStatusId
          },
          "Marketing Operations/URL": hubspotUrl,
          "Marketing Operations/Success metrics": successMetrics,
          "Marketing Operations/Media URL": mediaUrl,
          "Marketing Operations/Media Type": mediaType
        }
      }
    });
  } else {
    // CREATE new post
    allCommands.push({
      "command": "fibery.entity/create",
      "args": {
        "type": "Marketing Operations/All Marketing Projects",
        "entity": {
          "Marketing Operations/name": title,
          "Marketing Operations/Due Date": pubDate,
          "Marketing Operations/Content Type": {
            "fibery/id": "343cfa91-d5af-11f0-9651-01d88614008e"
          },
          "Marketing Operations/Status": {
            "fibery/id": fiberyStatusId
          },
          "Marketing Operations/URL": hubspotUrl,
          "Marketing Operations/Success metrics": successMetrics,
          "Marketing Operations/Media URL": mediaUrl,
          "Marketing Operations/Media Type": mediaType,
          "Marketing Operations/HubSpot ID": broadcastId
        }
      }
    });
  }
}

// Return single item with all commands batched
if (allCommands.length === 0) {
  return [{ json: { fiberyBody: "[]", message: "No posts to process" } }];
}

return [{ json: { fiberyBody: JSON.stringify(allCommands) } }];
